	import sailpoint.connector.Connector;
	import sailpoint.object.ResourceObject;
	import sailpoint.object.Rule;
	import sailpoint.tools.GeneralException;
	import sailpoint.tools.GeneralException;
	import sailpoint.tools.Message;
	import sailpoint.tools.Message.Type;
	import sailpoint.tools.Util;
	import sailpoint.object.*;
	import org.apache.log4j.Logger;

	if (object.getObjectType().compareTo(Connector.TYPE_ACCOUNT)==0) {
		Logger logger = Logger.getLogger("IAM_COE_BIRTHRIGHT_PROVISIONING");
		//logger.debug("Resource Object>>>>" +object.toXml());
		String status = (String)object.getAttribute("Status");

		if (status.equals("0")) {
			object.put("Status","Active");
			object.put("IIQDisabled",false);
		}
		else  {
			object.put("Status","Inactive");
			object.put("IIQDisabled",true);
		}
	}
	object.put("UserType","Employee");
	return object;
